import 'reflect-metadata';
import {
	closeTestingConnections,
	createTestingConnections,
	reloadTestingDatabases,
} from '../../../utils/test-utils';
import { DataSource } from '../../../../src/data-source/DataSource';
import { Post } from './entity/Post';
import { Category } from './entity/Category';
import { expect } from 'chai';

describe('transaction > transaction with full isolation support', () => {
	let connections: DataSource[];
	before(
		async () =>
			(connections = await createTestingConnections({
				entities: [__dirname + '/entity/*{.js,.ts}'],
				enabledDrivers: ['postgres'],
			})),
	);
	beforeEach(() => reloadTestingDatabases(connections));
	after(() => closeTestingConnections(connections));

	it('should execute all operations in a single transaction with READ UNCOMMITTED isolation level', () =>
		Promise.all(
			connections.map(async (connection) => {
				let postId: number | undefined = undefined,
					categoryId: number | undefined = undefined;

				await connection.manager.transaction('READ UNCOMMITTED', async (entityManager) => {
					const post = new Post();
					post.title = 'Post #1';
					await entityManager.save(post);

					const category = new Category();
					category.name = 'Category #1';
					await entityManager.save(category);

					postId = post.id;
					categoryId = category.id;
				});

				const post = await connection.manager.findOne(Post, {
					where: { title: 'Post #1' },
				});
				expect(post).not.to.be.null;
				post!.should.be.eql({
					id: postId,
					title: 'Post #1',
				});

				const category = await connection.manager.findOne(Category, {
					where: { name: 'Category #1' },
				});
				expect(category).not.to.be.null;
				category!.should.be.eql({
					id: categoryId,
					name: 'Category #1',
				});
			}),
		));

	it('should execute all operations in a single transaction with READ COMMITTED isolation level', () =>
		Promise.all(
			connections.map(async (connection) => {
				let postId: number | undefined = undefined,
					categoryId: number | undefined = undefined;

				await connection.manager.transaction('READ COMMITTED', async (entityManager) => {
					const post = new Post();
					post.title = 'Post #1';
					await entityManager.save(post);

					const category = new Category();
					category.name = 'Category #1';
					await entityManager.save(category);

					postId = post.id;
					categoryId = category.id;
				});

				const post = await connection.manager.findOne(Post, {
					where: { title: 'Post #1' },
				});
				expect(post).not.to.be.null;
				post!.should.be.eql({
					id: postId,
					title: 'Post #1',
				});

				const category = await connection.manager.findOne(Category, {
					where: { name: 'Category #1' },
				});
				expect(category).not.to.be.null;
				category!.should.be.eql({
					id: categoryId,
					name: 'Category #1',
				});
			}),
		));

	it('should execute all operations in a single transaction with REPEATABLE READ isolation level', () =>
		Promise.all(
			connections.map(async (connection) => {
				let postId: number | undefined = undefined,
					categoryId: number | undefined = undefined;

				await connection.manager.transaction('REPEATABLE READ', async (entityManager) => {
					const post = new Post();
					post.title = 'Post #1';
					await entityManager.save(post);

					const category = new Category();
					category.name = 'Category #1';
					await entityManager.save(category);

					postId = post.id;
					categoryId = category.id;
				});

				const post = await connection.manager.findOne(Post, {
					where: { title: 'Post #1' },
				});
				expect(post).not.to.be.null;
				post!.should.be.eql({
					id: postId,
					title: 'Post #1',
				});

				const category = await connection.manager.findOne(Category, {
					where: { name: 'Category #1' },
				});
				expect(category).not.to.be.null;
				category!.should.be.eql({
					id: categoryId,
					name: 'Category #1',
				});
			}),
		));

	it('should execute all operations in a single transaction with SERIALIZABLE isolation level', () =>
		Promise.all(
			connections.map(async (connection) => {
				let postId: number | undefined = undefined,
					categoryId: number | undefined = undefined;

				await connection.manager.transaction('SERIALIZABLE', async (entityManager) => {
					const post = new Post();
					post.title = 'Post #1';
					await entityManager.save(post);

					const category = new Category();
					category.name = 'Category #1';
					await entityManager.save(category);

					postId = post.id;
					categoryId = category.id;
				});

				const post = await connection.manager.findOne(Post, {
					where: { title: 'Post #1' },
				});
				expect(post).not.to.be.null;
				post!.should.be.eql({
					id: postId,
					title: 'Post #1',
				});

				const category = await connection.manager.findOne(Category, {
					where: { name: 'Category #1' },
				});
				expect(category).not.to.be.null;
				category!.should.be.eql({
					id: categoryId,
					name: 'Category #1',
				});
			}),
		));
});

import {
	instanceAiSetupCredentialAppliedKey,
	instanceAiSetupCredentialSelectionKey,
	readPendingInstanceAiSetupCredentialSelections,
	type InstanceAiSetupCredentialSelection,
} from '../instance-ai-setup-credential-selection';

const selection: InstanceAiSetupCredentialSelection = {
	selectionId: 'choice-1',
	credentialType: 'slackApi',
	credentialId: 'credential-1',
};
const itemId = 'workflow-1:credential:slackApi';

describe('readPendingInstanceAiSetupCredentialSelections', () => {
	it('reads only valid selections for the requested workflow', () => {
		expect(
			readPendingInstanceAiSetupCredentialSelections(
				{
					[instanceAiSetupCredentialSelectionKey(itemId)]: selection,
					[instanceAiSetupCredentialSelectionKey('workflow-2:credential:slackApi')]: selection,
					[instanceAiSetupCredentialSelectionKey('workflow-1:credential:gmailOAuth2')]: selection,
					[instanceAiSetupCredentialSelectionKey(`${itemId}:invalid`)]: { credentialId: 'id' },
				},
				'workflow-1',
			),
		).toEqual([{ itemId, selection }]);
	});

	it('keeps a newer choice pending when an earlier save finishes', () => {
		const metadata = {
			[instanceAiSetupCredentialSelectionKey(itemId)]: selection,
			[instanceAiSetupCredentialAppliedKey(itemId, 'older-choice')]: true,
		};
		expect(readPendingInstanceAiSetupCredentialSelections(metadata, 'workflow-1')).toEqual([
			{ itemId, selection },
		]);
		metadata[instanceAiSetupCredentialAppliedKey(itemId, selection.selectionId)] = true;
		metadata[instanceAiSetupCredentialAppliedKey(itemId, 'older-choice')] = true;
		expect(readPendingInstanceAiSetupCredentialSelections(metadata, 'workflow-1')).toEqual([]);
	});
});

import {
	OutboundHttp,
	type HttpRequestClient,
	type HttpRequestClientOptions,
} from '@n8n/backend-network';
import { startServer, type LocalServer } from '@n8n/backend-network/testing';
import { SsrfProtectionConfig } from '@n8n/config';
import { Container } from '@n8n/di';
import type { IHttpRequestOptions } from 'n8n-workflow';
import type { IncomingHttpHeaders } from 'node:http';

import { CiscoSecureEndpointApi } from '../CiscoSecureEndpointApi.credentials';

interface CapturedRequest {
	url: string;
	method: string;
	headers: IncomingHttpHeaders;
	body: string;
}

/**
 * Rewrites the credential's fixed vendor host to the local test server so the
 * real SSRF-guarded `OutboundHttp` stack is exercised over an actual socket;
 * only the destination host is swapped (loopback is reached via the allowlist).
 */
function rewriteToLocalServer(realOutbound: OutboundHttp, server: LocalServer): OutboundHttp {
	return {
		requests: (options?: HttpRequestClientOptions) => {
			const client = realOutbound.requests(options);
			const request = (async (reqOptions: IHttpRequestOptions) => {
				const target = new URL(reqOptions.url);
				return await client.request({
					...reqOptions,
					url: `${server.url}${target.pathname}${target.search}`,
				});
			}) as HttpRequestClient['request'];
			return { ...client, request };
		},
		transport: realOutbound.transport.bind(realOutbound),
	} as unknown as OutboundHttp;
}

/**
 * Real-socket coverage for the Cisco Secure Endpoint two-hop token exchange.
 * Drives the actual SSRF-guarded `OutboundHttp` factory to confirm both migrated
 * POSTs map equivalently end to end and the first token feeds the second hop.
 */
describe('CiscoSecureEndpointApi Credential (integration)', () => {
	const credential = new CiscoSecureEndpointApi();
	let server: LocalServer;
	let received: CapturedRequest[];

	beforeEach(async () => {
		received = [];
		server = await startServer((req, res) => {
			let body = '';
			req.on('data', (chunk) => (body += chunk));
			req.on('end', () => {
				received.push({
					url: req.url ?? '',
					method: req.method ?? '',
					headers: req.headers,
					body,
				});
				res.writeHead(200, { 'content-type': 'application/json' });
				if (req.url === '/iroh/oauth2/token') {
					res.end(JSON.stringify({ access_token: 'secure-x-token' }));
				} else {
					res.end(JSON.stringify({ access_token: 'secure-endpoint-token' }));
				}
			});
		});

		const config = new SsrfProtectionConfig();
		Object.assign(config, { enabled: true, allowedIpRanges: ['127.0.0.0/8'] });
		Container.set(SsrfProtectionConfig, config);
		Container.set(OutboundHttp, rewriteToLocalServer(Container.get(OutboundHttp), server));
	});

	afterEach(async () => {
		await server.close();
		Container.reset();
	});

	test('chains both token POSTs over a real socket and injects the final token', async () => {
		const result = await credential.authenticate(
			{ region: 'eu.amp', clientId: 'client-id', clientSecret: 'client-secret' },
			{ headers: {}, method: 'GET', url: 'https://api.eu.amp.cisco.com/v3/organizations' },
		);

		expect(received).toHaveLength(2);

		const [secureXReq, secureEndpointReq] = received;
		expect(secureXReq.method).toBe('POST');
		expect(secureXReq.url).toBe('/iroh/oauth2/token');
		expect(secureXReq.headers['content-type']).toBe('application/x-www-form-urlencoded');
		expect(secureXReq.headers.authorization).toMatch(/^Basic /);
		expect(new URLSearchParams(secureXReq.body).get('grant_type')).toBe('client_credentials');

		expect(secureEndpointReq.method).toBe('POST');
		expect(secureEndpointReq.url).toBe('/v3/access_tokens');
		// Second hop carries the first hop's token.
		expect(secureEndpointReq.headers.authorization).toBe('Bearer secure-x-token');
		expect(new URLSearchParams(secureEndpointReq.body).get('grant_type')).toBe(
			'client_credentials',
		);

		expect(result.headers?.Authorization).toBe('Bearer secure-endpoint-token');
	});
});

/**
 * Drives the real `OutboundHttp` client (no host rewrite) so the credential's own
 * allow-list is enforced against the actual token host. The restriction gate rejects
 * before any socket opens, so no request reaches the network.
 */
describe('CiscoSecureEndpointApi Credential (integration) allow-list enforcement', () => {
	const credential = new CiscoSecureEndpointApi();

	beforeEach(() => {
		const config = new SsrfProtectionConfig();
		Object.assign(config, { enabled: true, allowedIpRanges: ['127.0.0.0/8'] });
		Container.set(SsrfProtectionConfig, config);
	});

	afterEach(() => {
		Container.reset();
	});

	test('refuses the token exchange when the allow-list excludes the token host', async () => {
		await expect(
			credential.authenticate(
				{
					region: 'eu.amp',
					clientId: 'client-id',
					clientSecret: 'client-secret',
					allowedHttpRequestDomains: 'domains',
					allowedDomains: 'example.com',
				},
				{ headers: {}, method: 'GET', url: 'https://api.eu.amp.cisco.com/v3/organizations' },
			),
		).rejects.toThrow(/Domain not allowed/);
	});
});

import { OutboundHttp } from '@n8n/backend-network';
import { Container } from '@n8n/di';
import type { IHttpRequestOptions } from 'n8n-workflow';

import { CiscoSecureEndpointApi } from '../CiscoSecureEndpointApi.credentials';

describe('CiscoSecureEndpointApi Credential', () => {
	const credential = new CiscoSecureEndpointApi();

	const requestMock = vi.fn();
	const requestsMock = vi.fn(() => ({ request: requestMock }));

	const baseCredentials = {
		region: 'eu.amp',
		clientId: 'client-id',
		clientSecret: 'client-secret',
	};

	const requestOptions: IHttpRequestOptions = {
		headers: {},
		method: 'GET',
		url: 'https://api.eu.amp.cisco.com/v3/organizations',
	};

	beforeEach(() => {
		requestMock.mockReset();
		requestMock
			.mockResolvedValueOnce({ access_token: 'secure-x-token' })
			.mockResolvedValueOnce({ access_token: 'secure-endpoint-token' });
		requestsMock.mockClear();

		vi.spyOn(Container, 'get').mockImplementation((token: unknown) => {
			if (token === OutboundHttp) return { requests: requestsMock };
			throw new Error('unexpected DI token');
		});
	});

	it('should have correct properties', () => {
		expect(credential.name).toBe('ciscoSecureEndpointApi');
		expect(credential.displayName).toBe('Cisco Secure Endpoint (AMP) API');
	});

	describe('authenticate', () => {
		it('exchanges client credentials for the SecureX token using basic auth', async () => {
			await credential.authenticate(baseCredentials, requestOptions);

			expect(requestMock).toHaveBeenNthCalledWith(
				1,
				expect.objectContaining({
					url: 'https://visibility.eu.amp.cisco.com/iroh/oauth2/token',
					method: 'POST',
					auth: { username: 'client-id', password: 'client-secret' },
					body: 'grant_type=client_credentials',
					headers: {
						'Content-Type': 'application/x-www-form-urlencoded',
						Accept: 'application/json',
					},
					json: true,
				}),
			);
		});

		it('uses the SecureX token to request the Secure Endpoint access token', async () => {
			await credential.authenticate(baseCredentials, requestOptions);

			expect(requestMock).toHaveBeenNthCalledWith(
				2,
				expect.objectContaining({
					url: 'https://api.eu.amp.cisco.com/v3/access_tokens',
					method: 'POST',
					body: 'grant_type=client_credentials',
					headers: {
						'Content-Type': 'application/x-www-form-urlencoded',
						Accept: 'application/json',
						Authorization: 'Bearer secure-x-token',
					},
					json: true,
				}),
			);
		});

		it('requests the default safe client for the user-controlled token host', async () => {
			await credential.authenticate(baseCredentials, requestOptions);

			expect(requestsMock).toHaveBeenCalledWith();
		});

		it('rejects a region outside the supported list without issuing a request', async () => {
			await expect(
				credential.authenticate({ ...baseCredentials, region: 'not-a-region' }, requestOptions),
			).rejects.toThrow('Unsupported Cisco Secure Endpoint region');

			expect(requestMock).not.toHaveBeenCalled();
		});

		it("applies the credential's allowed domains to the token requests", async () => {
			await credential.authenticate(
				{
					...baseCredentials,
					allowedHttpRequestDomains: 'domains',
					allowedDomains: '*.amp.cisco.com',
				},
				requestOptions,
			);

			expect(requestMock).toHaveBeenCalledTimes(2);
			for (const [options] of requestMock.mock.calls) {
				expect(options).toEqual(expect.objectContaining({ allowedDomains: '*.amp.cisco.com' }));
			}
		});

		it('rejects a domains restriction with an empty allow-list before issuing a request', async () => {
			await expect(
				credential.authenticate(
					{ ...baseCredentials, allowedHttpRequestDomains: 'domains', allowedDomains: '' },
					requestOptions,
				),
			).rejects.toThrow('No allowed domains specified');

			expect(requestMock).not.toHaveBeenCalled();
		});

		it('attaches the Secure Endpoint access token to the outgoing request', async () => {
			const result = await credential.authenticate(baseCredentials, requestOptions);

			expect(result.headers?.Authorization).toBe('Bearer secure-endpoint-token');
		});
	});
});

import { OutboundHttp } from '@n8n/backend-network';
import { Container } from '@n8n/di';
import type {
	ICredentialDataDecryptedObject,
	IHttpRequestHelper,
	INodeProperties,
} from 'n8n-workflow';
import { OperationalError, jsonParse } from 'n8n-workflow';

import { TOKEN_REQUEST_TIMEOUT } from '../common/token-request';
import {
	MicrosoftEntraServicePrincipalApi,
	getAccessToken,
} from '../MicrosoftEntraServicePrincipalApi.credentials';

const STATIC_NO_TOKEN_MESSAGE = 'Microsoft Entra authentication did not return an access token';

const TEST_PRIVATE_KEY =
	'-----BEGIN PRIVATE KEY----------END PRIVATE KEY-----';

const TEST_CERTIFICATE =
	'-----BEGIN CERTIFICATE----------END CERTIFICATE-----';

// SHA-1 thumbprint of TEST_CERTIFICATE, base64url-encoded (the JWT `x5t` header value).
const EXPECTED_X5T = 'aK3rs6ongTQ6RIYSBIx5LFJD-Q4';

describe('MicrosoftEntraServicePrincipalApi Credential', () => {
	const credential = new MicrosoftEntraServicePrincipalApi();

	const requestMock = vi.fn();
	const requestsMock = vi.fn(() => ({ request: requestMock }));

	// `this` for preAuthentication is unused now that the token POST goes through the
	// shared HTTP client, but the signature still requires the helper context.
	const helpers = { helpers: {} } as unknown as IHttpRequestHelper;

	const baseCredentials = {
		authentication: 'clientSecret',
		tenantId: 'tenant-id',
		clientId: 'client-id',
		clientSecret: 'client-secret',
	};

	const callPreAuthentication = async (credentials: ICredentialDataDecryptedObject) =>
		await credential.preAuthentication.call(helpers, credentials);

	beforeEach(() => {
		requestMock.mockReset();
		requestMock.mockResolvedValue({ access_token: 'abc', token_type: 'Bearer', expires_in: 3599 });
		requestsMock.mockClear();

		// Stub ONLY OutboundHttp. `getTokenRequestClient` resolves nothing else from
		// the container, so reaching any other DI token signals a regression and
		// must fail loudly.
		vi.spyOn(Container, 'get').mockImplementation((token: unknown) => {
			if (token === OutboundHttp) return { requests: requestsMock };
			throw new Error('unexpected DI token');
		});
	});

	it('should have correct static properties', () => {
		expect(credential.name).toBe('microsoftEntraServicePrincipalApi');
		expect(credential.displayName).toBe('Microsoft Entra Service Principal');
		expect(credential.documentationUrl).toBe('microsoftentraserviceprincipal');
		expect(credential.icon).toBe('file:icons/Microsoft.svg');

		const accessToken = credential.properties.find(
			(property: INodeProperties) => property.name === 'accessToken',
		);
		expect(accessToken?.type).toBe('hidden');
		expect(accessToken?.typeOptions?.expirable).toBe(true);

		const authentication = credential.properties.find(
			(property: INodeProperties) => property.name === 'authentication',
		);
		expect(authentication?.type).toBe('options');
		expect(authentication?.default).toBe('clientSecret');
		expect(
			authentication?.options?.map((option) => ('value' in option ? option.value : '')),
		).toEqual(['clientSecret', 'certificate']);

		const clientSecret = credential.properties.find(
			(property: INodeProperties) => property.name === 'clientSecret',
		);
		expect(clientSecret?.displayOptions?.show?.authentication).toEqual(['clientSecret']);
		expect(clientSecret?.typeOptions?.password).toBe(true);

		const privateKey = credential.properties.find(
			(property: INodeProperties) => property.name === 'privateKey',
		);
		expect(privateKey?.displayOptions?.show?.authentication).toEqual(['certificate']);
		expect(privateKey?.typeOptions?.password).toBe(true);

		const certificate = credential.properties.find(
			(property: INodeProperties) => property.name === 'certificate',
		);
		expect(certificate?.displayOptions?.show?.authentication).toEqual(['certificate']);

		// App-only access has no granular-scope freedom, so there is no editable scope field;
		// the scope is derived from the selected cloud at mint time.
		const scope = credential.properties.find(
			(property: INodeProperties) => property.name === 'scope',
		);
		expect(scope).toBeUndefined();

		const setupNotice = credential.properties.find(
			(property: INodeProperties) => property.name === 'setupNotice',
		);
		expect(setupNotice?.type).toBe('notice');
		expect(setupNotice?.displayName).not.toContain('Organization.Read.All');
		expect(setupNotice?.displayName).not.toContain('Directory.Read.All');

		const graphApiBaseUrl = credential.properties.find(
			(property: INodeProperties) => property.name === 'graphApiBaseUrl',
		);
		expect(graphApiBaseUrl?.type).toBe('options');
		expect(
			graphApiBaseUrl?.options?.map((option) => ('value' in option ? option.value : '')),
		).toEqual([
			'https://graph.microsoft.com',
			'https://graph.microsoft.us',
			'https://dod-graph.microsoft.us',
			'https://microsoftgraph.chinacloudapi.cn',
		]);
	});

	it('should have the expected credential test request shape', () => {
		expect(credential.test.request.url).toBe('/v1.0/');
		expect(credential.test.request.method).toBe('GET');
		expect(credential.test.request.baseURL).toBe(
			'={{$credentials.graphApiBaseUrl || "https://graph.microsoft.com"}}',
		);
	});

	describe('preAuthentication', () => {
		it('mints a token and returns it as { accessToken }', async () => {
			requestMock.mockResolvedValueOnce({
				access_token: 'abc',
				expires_in: 3599,
				token_type: 'Bearer',
			});

			const result = await callPreAuthentication(baseCredentials);

			expect(result).toEqual({ accessToken: 'abc' });
		});

		it('mints when invoked with an empty cached accessToken (the Test button path)', async () => {
			requestMock.mockResolvedValueOnce({ access_token: 'minted-on-empty' });

			const result = await callPreAuthentication({ ...baseCredentials, accessToken: '' });

			expect(requestMock).toHaveBeenCalledTimes(1);
			expect(result).toEqual({ accessToken: 'minted-on-empty' });
		});

		it('posts a correct client_credentials token request to the global host', async () => {
			await callPreAuthentication(baseCredentials);

			expect(requestMock).toHaveBeenCalledTimes(1);
			expect(requestMock).toHaveBeenCalledWith(
				expect.objectContaining({
					method: 'POST',
					url: 'https://login.microsoftonline.com/tenant-id/oauth2/v2.0/token',
					body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=client-secret',
					headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
					json: true,
					timeout: TOKEN_REQUEST_TIMEOUT,
				}),
			);
		});

		it('trims whitespace from tenantId, clientId and clientSecret', async () => {
			await callPreAuthentication({
				...baseCredentials,
				tenantId: '  tenant-id  ',
				clientId: '  client-id  ',
				clientSecret: '  client-secret  ',
			});

			expect(requestMock).toHaveBeenCalledWith(
				expect.objectContaining({
					url: 'https://login.microsoftonline.com/tenant-id/oauth2/v2.0/token',
					body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=client-secret',
				}),
			);
		});

		it('mints via the SSRF-exempt fixed-vendor client', async () => {
			await callPreAuthentication(baseCredentials);

			// `{ useDefaultSsrfPolicy: 'unsafe' }` proves the fixed-vendor path; the `throw on
			// other DI token` mock proves nothing else is resolved from the container.
			expect(requestsMock).toHaveBeenCalledWith({ useDefaultSsrfPolicy: 'unsafe' });
		});

		it('re-mints on each call without internal memoization', async () => {
			// The 401 trigger that drives re-minting on expiry lives in core
			// (request-helpers/authentication.ts) and is covered by core tests; here we only
			// prove the credential side has no caching, so that retry has a real re-mint to drive.
			requestMock.mockResolvedValueOnce({ access_token: 'tok1' });
			requestMock.mockResolvedValueOnce({ access_token: 'tok2' });

			const first = await callPreAuthentication(baseCredentials);
			const second = await callPreAuthentication(baseCredentials);

			expect(first).toEqual({ accessToken: 'tok1' });
			expect(second).toEqual({ accessToken: 'tok2' });
			expect(requestMock).toHaveBeenCalledTimes(2);
		});

		describe('scope derivation', () => {
			it('derives the global Graph resource scope when the base is global', async () => {
				await callPreAuthentication({
					...baseCredentials,
					graphApiBaseUrl: 'https://graph.microsoft.com',
				});

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=client-secret',
					}),
				);
			});

			it('derives the global Graph resource scope when the base is omitted', async () => {
				await callPreAuthentication(baseCredentials);

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=client-secret',
					}),
				);
			});

			it('derives the sovereign Graph resource scope from a US Gov base', async () => {
				await callPreAuthentication({
					...baseCredentials,
					graphApiBaseUrl: 'https://graph.microsoft.us',
				});

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.us%2F.default&client_secret=client-secret',
					}),
				);
			});

			it('derives the sovereign Graph resource scope from a trailing-slash US Gov base', async () => {
				await callPreAuthentication({
					...baseCredentials,
					graphApiBaseUrl: 'https://graph.microsoft.us/',
				});

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.us%2F.default&client_secret=client-secret',
					}),
				);
			});
		});

		describe('certificate authentication', () => {
			const certCredentials = {
				authentication: 'certificate',
				tenantId: 'tenant-id',
				clientId: 'client-id',
				clientSecret: 'stale-secret-should-not-be-sent',
				privateKey: TEST_PRIVATE_KEY,
				certificate: TEST_CERTIFICATE,
			};

			const postedBody = () =>
				new URLSearchParams((requestMock.mock.calls[0][0] as { body: string }).body);

			it('signs a client_assertion instead of sending a client_secret', async () => {
				await callPreAuthentication(certCredentials);

				const body = postedBody();
				expect(body.get('grant_type')).toBe('client_credentials');
				expect(body.get('client_id')).toBe('client-id');
				expect(body.get('client_assertion_type')).toBe(
					'urn:ietf:params:oauth:client-assertion-type:jwt-bearer',
				);
				expect(body.has('client_secret')).toBe(false);
				expect((requestMock.mock.calls[0][0] as { body: string }).body).not.toContain(
					'stale-secret-should-not-be-sent',
				);

				// The assertion is a JWT (header.payload.signature) whose `aud` is the token endpoint.
				const assertion = body.get('client_assertion') ?? '';
				const [headerSeg, payloadSeg] = assertion.split('.');
				expect(assertion.split('.')).toHaveLength(3);

				// The `x5t` header is the SHA-1 thumbprint of the certificate — asserting it proves
				// the credential forwarded *this* certificate into the assertion, not just any JWT.
				const header = jsonParse<{ x5t: string }>(
					Buffer.from(headerSeg, 'base64url').toString('utf8'),
				);
				expect(header.x5t).toBe(EXPECTED_X5T);

				const payload = jsonParse<{ aud: string; iss: string }>(
					Buffer.from(payloadSeg, 'base64url').toString('utf8'),
				);
				expect(payload.aud).toBe('https://login.microsoftonline.com/tenant-id/oauth2/v2.0/token');
				expect(payload.iss).toBe('client-id');
			});

			it.each([
				['missing privateKey', { ...certCredentials, privateKey: '' }],
				['missing certificate', { ...certCredentials, certificate: '' }],
			])('rejects before any token POST when %s', async (_label, credentials) => {
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra credentials are incomplete',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});
		});

		describe('sovereign login host derivation', () => {
			const expectTokenHost = async (
				graphApiBaseUrl: string,
				expectedTokenUrl: string,
			): Promise<void> => {
				await callPreAuthentication({ ...baseCredentials, graphApiBaseUrl });

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({ url: expectedTokenUrl }),
				);
			};

			it('derives the China login host from the China Graph base', async () => {
				await expectTokenHost(
					'https://microsoftgraph.chinacloudapi.cn',
					'https://login.partner.microsoftonline.cn/tenant-id/oauth2/v2.0/token',
				);
			});

			it('derives the US Gov login host from the US Gov Graph base', async () => {
				await expectTokenHost(
					'https://graph.microsoft.us',
					'https://login.microsoftonline.us/tenant-id/oauth2/v2.0/token',
				);
			});

			it('normalizes a trailing slash before deriving the login host', async () => {
				await expectTokenHost(
					'https://graph.microsoft.us/',
					'https://login.microsoftonline.us/tenant-id/oauth2/v2.0/token',
				);
			});
		});

		describe('validation before any network call', () => {
			it.each([
				['missing tenantId', { ...baseCredentials, tenantId: '' }],
				['missing clientId', { ...baseCredentials, clientId: '' }],
				['missing clientSecret', { ...baseCredentials, clientSecret: '' }],
			])('rejects with an incomplete-credentials error when %s', async (_label, credentials) => {
				await expect(callPreAuthentication(credentials)).rejects.toThrow(OperationalError);
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra credentials are incomplete',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});

			it('rejects an invalid tenantId before any token POST', async () => {
				const credentials = { ...baseCredentials, tenantId: 'https://evil.com' };
				await expect(callPreAuthentication(credentials)).rejects.toThrow(OperationalError);
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra tenant ID is not a valid GUID or domain',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});

			it('rejects an unrecognized graphApiBaseUrl before any token POST', async () => {
				// An API-created credential can carry an arbitrary base URL; the token must never be
				// minted for it, otherwise the test request would send a valid Graph bearer elsewhere.
				const credentials = { ...baseCredentials, graphApiBaseUrl: 'https://evil.com' };
				await expect(callPreAuthentication(credentials)).rejects.toThrow(OperationalError);
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra Graph API base URL is not a recognized Microsoft cloud',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});
		});

		describe('malformed token response', () => {
			it.each([
				['no access_token field', { token_type: 'Bearer' }],
				['empty access_token', { access_token: '' }],
				['null access_token', { access_token: null }],
				['an AADSTS error body', { error: 'invalid_client', error_description: 'AADSTS7000215' }],
				['an empty object', {}],
			])(
				'rejects with an OperationalError carrying the static message for %s',
				async (_label, response) => {
					requestMock.mockResolvedValueOnce(response);

					const error = await callPreAuthentication(baseCredentials).catch((e: unknown) => e);

					expect(error).toBeInstanceOf(OperationalError);
					expect((error as OperationalError).message).toBe(STATIC_NO_TOKEN_MESSAGE);
				},
			);
		});
	});

	describe('getAccessToken', () => {
		it('accepts a GUID tenantId', async () => {
			await getAccessToken({
				...baseCredentials,
				tenantId: '12345678-1234-1234-1234-123456789abc',
			});

			expect(requestMock).toHaveBeenCalledWith(
				expect.objectContaining({
					url: 'https://login.microsoftonline.com/12345678-1234-1234-1234-123456789abc/oauth2/v2.0/token',
				}),
			);
		});
	});

	describe('authenticate', () => {
		it('attaches the cached bearer token to the request', async () => {
			const result = await credential.authenticate(
				{ accessToken: 'cached' },
				{ headers: {}, method: 'GET', url: '/v1.0/' },
			);

			expect(result.headers?.Authorization).toBe('Bearer cached');
		});

		it('reuses the cached token without performing a token exchange', async () => {
			const result = await credential.authenticate(
				{ ...baseCredentials, accessToken: 'cached' },
				{ headers: {}, method: 'GET', url: '/v1.0/' },
			);

			expect(result.headers?.Authorization).toBe('Bearer cached');
			expect(requestMock).not.toHaveBeenCalled();
		});

		it('reuses a single minted token across multiple requests (AC#3)', async () => {
			requestMock.mockResolvedValueOnce({ access_token: 'abc' });
			const { accessToken } = await callPreAuthentication(baseCredentials);

			const credentials = { ...baseCredentials, accessToken };
			for (let i = 0; i < 3; i++) {
				const result = await credential.authenticate(credentials, {
					headers: {},
					method: 'GET',
					url: `/v1.0/?attempt=${i}`,
				});
				expect(result.headers?.Authorization).toBe('Bearer abc');
			}

			expect(requestMock).toHaveBeenCalledTimes(1);
		});
	});
});

import { EventService } from '@n8n/backend-services';
import { createTeamProject, linkUserToProject, testDb } from '@n8n/backend-test-utils';
import { LICENSE_FEATURES } from '@n8n/constants';
import type { Project, User } from '@n8n/db';
import { Container } from '@n8n/di';

import { LoadNodesAndCredentials } from '@/load-nodes-and-credentials';
import { TypeAvailabilityPolicyRepository } from '@/modules/type-availability-policies/database/repositories/type-availability-policy.repository';
import { createMemberWithApiKey, createOwnerWithApiKey } from '@test-integration/db/users';
import * as utils from '@test-integration/utils';

const testServer = utils.setupTestServer({
	endpointGroups: ['publicApi'],
	modules: ['type-availability-policies'],
	enabledFeatures: [LICENSE_FEATURES.TYPE_AVAILABILITY_POLICIES],
});

let owner: User;
let unscopedOwner: User;
let projectAdmin: User;
let projectEditor: User;
let otherProjectAdmin: User;
let project: Project;
let otherProject: Project;

const projectRoute = (projectId: string) => `/credential-type-policies/projects/${projectId}`;

const ALLOW_ALL = { rules: [], defaultAction: 'allow', version: 0 };
const DENY_RULE = { id: 'r1', action: 'deny', selector: { kind: 'name', value: 'slackApi' } };
const DELEGATE_RULE = {
	id: 'r2',
	action: 'delegate',
	selector: { kind: 'name', value: 'slackApi' },
};
const OTHER_KIND_RULE = {
	id: 'other-r1',
	action: 'deny' as const,
	selector: { kind: 'name' as const, value: 'other.thing' },
};

const EFFECTIVE_KEYS = ['scopeId', 'rules', 'defaultAction', 'version'];
const DOCUMENT_KEYS = ['id', 'kind', 'rules', 'version', 'updatedBy', 'createdAt', 'updatedAt'];

beforeAll(async () => {
	owner = await createOwnerWithApiKey();
	unscopedOwner = await createOwnerWithApiKey({ scopes: ['tag:list'] });
	projectAdmin = await createMemberWithApiKey({ scopes: ['credentialTypePolicy:manage'] });
	projectEditor = await createMemberWithApiKey({ scopes: ['credentialTypePolicy:manage'] });
	otherProjectAdmin = await createMemberWithApiKey({ scopes: ['credentialTypePolicy:manage'] });

	project = await createTeamProject('Policy project', projectAdmin);
	otherProject = await createTeamProject('Other project', otherProjectAdmin);
	await linkUserToProject(projectEditor, project, 'project:editor');
});

afterEach(async () => {
	await testDb.truncate([
		'TypeAvailabilityPolicyAttachment',
		'TypeAvailabilityPolicyScope',
		'TypeAvailabilityPolicy',
	]);
});

// Fixture rules name `slackApi`; without it loaded, every write would also warn `notLoaded`.
beforeEach(() => {
	vi.spyOn(Container.get(LoadNodesAndCredentials), 'knownCredentials', 'get').mockReturnValue({
		slackApi: { className: '', sourcePath: '' },
	});
});

/**
 * Least privilege first: the API-key scope check and the RBAC check are independent, so a key
 * that lacks the scope and a key whose user lacks the RBAC grant are both rejected with 403.
 */
describe('credential type policies public API authorization', () => {
	test('an unauthenticated caller is rejected with 401', async () => {
		const response = await testServer
			.publicApiAgentWithoutApiKey()
			.get('/credential-type-policies/instance');

		expect(response.statusCode).toBe(401);
	});

	test.each([
		['GET', '/credential-type-policies/instance'],
		['PUT', '/credential-type-policies/instance'],
		['GET', '/credential-type-policies/policies'],
		['POST', '/credential-type-policies/policies'],
		['GET', '/credential-type-policies/policies/does-not-exist'],
		['PUT', '/credential-type-policies/policies/does-not-exist'],
		['DELETE', '/credential-type-policies/policies/does-not-exist'],
		['GET', '/credential-type-policies/scopes/does-not-exist/attachments'],
		['PUT', '/credential-type-policies/scopes/does-not-exist/attachments'],
	])('%s %s rejects an owner key without the scope with 403', async (method, path) => {
		const agent = testServer.publicApiAgentFor(unscopedOwner);
		const response = await (method === 'GET'
			? agent.get(path)
			: method === 'POST'
				? agent.post(path).send({})
				: method === 'PUT'
					? agent
							.put(path)
							.send(path.endsWith('/attachments') ? { attachments: [], version: 0 } : {})
					: agent.delete(path));

		expect(response.statusCode).toBe(403);
	});

	test('GET/PUT on a project rejects an owner key without the scope with 403', async () => {
		const agent = testServer.publicApiAgentFor(unscopedOwner);

		expect((await agent.get(projectRoute(project.id))).statusCode).toBe(403);
		expect((await agent.put(projectRoute(project.id)).send(ALLOW_ALL)).statusCode).toBe(403);
	});

	test.each([
		['GET', '/credential-type-policies/instance'],
		['PUT', '/credential-type-policies/instance'],
		['GET', '/credential-type-policies/policies'],
		['POST', '/credential-type-policies/policies'],
		['GET', '/credential-type-policies/policies/does-not-exist'],
		['PUT', '/credential-type-policies/policies/does-not-exist'],
		['DELETE', '/credential-type-policies/policies/does-not-exist'],
		['GET', '/credential-type-policies/scopes/does-not-exist/attachments'],
		['PUT', '/credential-type-policies/scopes/does-not-exist/attachments'],
	])(
		'%s %s rejects a project admin with 403 (instance routes are global-only)',
		async (method, path) => {
			const agent = testServer.publicApiAgentFor(projectAdmin);
			const response = await (method === 'GET'
				? agent.get(path)
				: method === 'POST'
					? agent.post(path).send({})
					: method === 'PUT'
						? agent
								.put(path)
								.send(path.endsWith('/attachments') ? { attachments: [], version: 0 } : {})
						: agent.delete(path));

			expect(response.statusCode).toBe(403);
		},
	);

	test('GET/PUT on a project rejects a project editor with 403', async () => {
		const agent = testServer.publicApiAgentFor(projectEditor);

		expect((await agent.get(projectRoute(project.id))).statusCode).toBe(403);
		expect((await agent.put(projectRoute(project.id)).send(ALLOW_ALL)).statusCode).toBe(403);
	});

	test('PUT on a project rejects the admin of another project with 403 and writes nothing', async () => {
		const response = await testServer
			.publicApiAgentFor(otherProjectAdmin)
			.put(projectRoute(project.id))
			.send({ ...ALLOW_ALL, defaultAction: 'deny' });

		expect(response.statusCode).toBe(403);

		const unchanged = await testServer
			.publicApiAgentFor(projectAdmin)
			.get(projectRoute(project.id));
		expect(unchanged.body.version).toBe(0);
	});

	test('the admin of the project and an instance owner are not rejected by the scope check', async () => {
		expect(
			(await testServer.publicApiAgentFor(projectAdmin).get(projectRoute(project.id))).statusCode,
		).toBe(200);
		expect(
			(await testServer.publicApiAgentFor(owner).get(projectRoute(project.id))).statusCode,
		).toBe(200);
	});
});

describe('credential type policies public API license gating', () => {
