			.send({
				attachments: [
					{ policyId: 'p1', priority: 0, isFloor: false },
					{ policyId: 'p2', priority: 0, isFloor: false },
				],
				version: instancePut.body.version,
			});
		expect(duplicateSlot.statusCode).toBe(400);
	});

	test('PUT on an unknown scope returns 404', async () => {
