describe('reconcileNodeToolGatewayCredentials', () => {
	it('auto-assigns the managed credential to a covered, empty, required slot', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('leaves a real credential untouched (BYOK wins)', () => {
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { id: 'c1', name: 'My Slack' } }),
		];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: { id: 'c1', name: 'My Slack' } });
	});

	it('assigns the managed credential over a slot whose id was cleared by sanitization', () => {
		// sanitizeUnknownAgentCredentials clears an inaccessible id to '' — the
		// slot is effectively empty (validation flags it missing) and must pick
		// up the managed credential like any other empty slot.
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { id: '', name: 'Old' } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('does not assign for a service the gateway does not cover', () => {
		const tools = [nodeTool('n8n-nodes-base.notionTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['notionApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('does not auto-assign to an HTTP request tool even when the gateway covers it', () => {
		// Defense-in-depth mirroring MCP: an HTTP node calls a user-controlled
		// URL, so a managed credential is never attached automatically.
		const tools = [nodeTool('n8n-nodes-base.httpRequestTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['httpBasicAuth']),
			{
				nodes: ['n8n-nodes-base.httpRequest'],
				credentialTypes: ['httpBasicAuth'],
				providerConfig: {},
			} as unknown as AiGatewayConfigDto,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('keeps an eligible inbound managed marker on an HTTP request tool (explicit opt-in)', () => {
		const tools = [nodeTool('n8n-nodes-base.httpRequestTool', { httpBasicAuth: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['httpBasicAuth']),
			{
				nodes: ['n8n-nodes-base.httpRequest'],
				credentialTypes: ['httpBasicAuth'],
				providerConfig: {},
			} as unknown as AiGatewayConfigDto,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ httpBasicAuth: SENTINEL });
	});

	it('does not auto-assign when the project already has a credential of the type (own credential wins)', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			new Set(['slackApi']),
		);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('keeps an explicit inbound managed marker even when the project has a credential of the type', () => {
		// An inbound marker is an explicit choice (manual toggle or the user
		// asking the builder for n8n credits) — own credentials must not veto it.
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			new Set(['slackApi']),
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('does not switch auth to a sibling type the project has a credential for', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			new Set(['serviceApiKey']),
		);
		expect(tools[0].node.credentials).toBeUndefined();
		expect(tools[0].node.nodeParameters).toEqual({});
	});

	it('switches auth to a supported sibling credential type when the displayed type is unsupported', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];

		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);

		expect(tools[0].node.credentials).toEqual({ serviceApiKey: SENTINEL });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKey' });
	});

	it('switches auth while preserving unrelated parameters when the auth selector relies on its default', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];
		tools[0].node.nodeParameters = { operation: 'split' };

		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription({
				...multiAuthNodeDescription,
				properties: [
					{
						displayName: 'Operation',
						name: 'operation',
						type: 'options',
						options: [{ name: 'Split', value: 'split' }],
						default: 'split',
					},
					...multiAuthNodeDescription.properties,
				],
			}),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);

		expect(tools[0].node.credentials).toEqual({ serviceApiKey: SENTINEL });
		expect(tools[0].node.nodeParameters).toEqual({
			operation: 'split',
			authentication: 'apiKey',
		});
	});

	it('does not rewrite an auth parameter that already activates the supported credential', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];
		tools[0].node.nodeParameters = { authentication: 'apiKeyLegacy' };

		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription({
				...multiAuthNodeDescription,
				credentials: [
					{
						name: 'serviceApiKey',
						displayOptions: { show: { authentication: ['apiKey', 'apiKeyLegacy'] } },
					},
				],
			}),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);

		expect(tools[0].node.credentials).toEqual({ serviceApiKey: SENTINEL });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKeyLegacy' });
	});

	it('activates the auth parameter for an explicit marker on an inactive alternate auth slot', () => {
		// Marker on the API-key slot while `authentication` still defaults to
		// OAuth (and the project owns the OAuth type): without activation the
		// marker is inert and the tool cannot run.
		const tools = [nodeTool('n8n-nodes-base.serviceTool', { serviceApiKey: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			new Set(['serviceOAuth2Api']),
		);
		expect(tools[0].node.credentials).toEqual({ serviceApiKey: SENTINEL });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKey' });
	});

	it('leaves parameters untouched when the marked slot is already active', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool', { serviceApiKey: { ...SENTINEL } })];
		tools[0].node.nodeParameters = { authentication: 'apiKey' };
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ serviceApiKey: SENTINEL });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKey' });
	});

	it('keeps an eligible marker on a slot the node description does not declare', () => {
		// HTTP predefined credential types are not in description.credentials, so
		// no activation resolves; the explicit marker must survive untouched.
		const tools = [nodeTool('n8n-nodes-base.httpRequestTool', { serviceApiKey: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials([]),
			{
				nodes: ['n8n-nodes-base.httpRequest'],
				credentialTypes: ['serviceApiKey'],
				providerConfig: {},
			} as unknown as AiGatewayConfigDto,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ serviceApiKey: SENTINEL });
		expect(tools[0].node.nodeParameters).toEqual({});
	});

	it('deletes an inbound managed marker on an uncovered slot (trust gate)', () => {
		const tools = [nodeTool('n8n-nodes-base.notionTool', { notionApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['notionApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({});
	});

	it('canonicalizes an eligible managed marker, dropping smuggled fields', () => {
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', {
				slackApi: {
					id: null,
					name: 'hacked',
					__aiGatewayManaged: true,
					injected: 'x',
				} as never,
			}),
		];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('drops all managed markers when no gateway config is available', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			undefined,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({});
	});

	it('drops managed markers when the node type cannot be resolved', () => {
		const nodeTypes = mock<NodeTypes>();
		nodeTypes.getByNameAndVersion.mockImplementation(() => {
			throw new Error('unknown node type');
		});
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(tools, nodeTypes, GATEWAY_CONFIG, NO_OWNED);
		expect(tools[0].node.credentials).toEqual({});
	});
});

describe('listAiGatewayManagedCredentialTypes', () => {
	it('returns a type whose every required slot is served by a managed credential', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		expect(
			listAiGatewayManagedCredentialTypes(tools, nodeTypesWithCredentials(['slackApi'])),
		).toEqual(['slackApi']);
	});

	it('treats a real credential of the type as satisfying the slot', () => {
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } }),
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { id: 'c1', name: 'My Slack' } }),
		];
		expect(
			listAiGatewayManagedCredentialTypes(tools, nodeTypesWithCredentials(['slackApi'])),
		).toEqual(['slackApi']);
	});

	it('excludes a managed type that still has an empty required slot on another tool', () => {
		// Per-operation coverage: one tool runs a covered operation on n8n credits,
		// another needs a real credential for an uncovered one — so the type must
		// keep prompting rather than be suppressed globally.
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } }),
			nodeTool('n8n-nodes-base.slackTool'),
		];
		expect(
			listAiGatewayManagedCredentialTypes(tools, nodeTypesWithCredentials(['slackApi'])),
		).toEqual([]);
	});

	it('ignores non-node tools and unresolvable node types', () => {
		const nodeTypes = mock<NodeTypes>();
		nodeTypes.getByNameAndVersion.mockImplementation(() => {
			throw new Error('unknown node type');
		});
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		expect(listAiGatewayManagedCredentialTypes(tools, nodeTypes)).toEqual([]);
	});
});

describe('assignCredentialToNodeTools', () => {
	const credential = { id: 'g1', name: 'Gmail account' };

	it('fills every empty slot of the type and counts them', () => {
		const tools = [nodeTool('n8n-nodes-base.gmailTool'), nodeTool('n8n-nodes-base.gmailTool')];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithCredentials(['gmailOAuth2']),
			'gmailOAuth2',
			credential,
		);
		expect(filled).toBe(2);
		expect(tools.map((t) => t.node.credentials)).toEqual([
			{ gmailOAuth2: credential },
			{ gmailOAuth2: credential },
		]);
	});

	it('keeps a real credential and a managed marker', () => {
		const tools = [
			nodeTool('n8n-nodes-base.gmailTool', { gmailOAuth2: { id: 'other', name: 'Other' } }),
			nodeTool('n8n-nodes-base.gmailTool', { gmailOAuth2: { ...SENTINEL } }),
		];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithCredentials(['gmailOAuth2']),
			'gmailOAuth2',
			credential,
		);
		expect(filled).toBe(0);
		expect(tools[0].node.credentials).toEqual({ gmailOAuth2: { id: 'other', name: 'Other' } });
		expect(tools[1].node.credentials).toEqual({ gmailOAuth2: SENTINEL });
	});

	it('skips a node whose type does not declare the credential', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool')];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			'gmailOAuth2',
			credential,
		);
		expect(filled).toBe(0);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('skips a slot hidden by the current authentication option', () => {
		const tools = [nodeTool('n8n-nodes-base.service')];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			'serviceApiKey',
			{ id: 'k1', name: 'Key' },
		);
		expect(filled).toBe(0);
	});
});

import type {
	CredentialTypePolicyEffectiveWriteResultPublicDto,
	PutCredentialTypeInstancePolicyDto,
	PutCredentialTypeProjectPolicyDto,
} from '@n8n/api-types';
import type { ModuleRegistry } from '@n8n/backend-common';
import { LICENSE_FEATURES } from '@n8n/constants';
import type { AuthenticatedRequest, User } from '@n8n/db';
import { ControllerRegistryMetadata } from '@n8n/decorators';
import { Container } from '@n8n/di';
import type { Response } from 'express';
import { mock } from 'vitest-mock-extended';

import { ServiceUnavailableError } from '@n8n/errors';
import { CREDENTIAL_TYPES_KIND } from '@/modules/type-availability-policies/constants';
import type { EffectivePolicy } from '@/modules/type-availability-policies/type-availability-policy.service';
import { TypeAvailabilityPolicyService } from '@/modules/type-availability-policies/type-availability-policy.service';

import { CredentialTypePoliciesPublicController } from '../credential-type-policies.public.controller';

/**
 * Every public route must carry the same guards as the internal controllers it mirrors: the
 * node type policies license feature (shared with credential type policies), the
 * `credentialTypePolicy:manage` API-key scope, and a `credentialTypePolicy:manage` RBAC check
 * that is global-only everywhere except on the two project-scoped routes.
 */
describe('CredentialTypePoliciesPublicController route metadata', () => {
	const metadata = Container.get(ControllerRegistryMetadata).getControllerMetadata(
		CredentialTypePoliciesPublicController as never,
	);
	const routeCases = Array.from(metadata.routes.entries()).map(([handlerName, route]) => ({
		handlerName,
		route,
	}));
	const projectHandlers = new Set([
		'getCredentialTypeProjectPolicy',
		'putCredentialTypeProjectPolicy',
	]);

	it('registers every route of the internal instance and project controllers', () => {
		expect(routeCases.map(({ handlerName }) => handlerName).sort()).toEqual(
			[
				'createCredentialTypePolicyDocument',
				'deleteCredentialTypePolicyDocument',
				'getCredentialTypeInstancePolicy',
				'getCredentialTypePolicyAttachments',
				'getCredentialTypePolicyDocument',
				'getCredentialTypeProjectPolicy',
				'listCredentialTypePolicyDocuments',
				'putCredentialTypeInstancePolicy',
				'putCredentialTypeProjectPolicy',
				'replaceCredentialTypePolicyAttachments',
				'updateCredentialTypePolicyDocument',
			].sort(),
		);
	});

	it.each(routeCases)(
		'$handlerName requires the credentialTypePolicy:manage API key scope',
		({ route }) => {
			expect(route.apiKeyScope).toBe('credentialTypePolicy:manage');
		},
	);

	it.each(routeCases)(
		'$handlerName is gated by a credentialTypePolicy:manage RBAC check',
		({ route }) => {
			expect(route.accessScope?.scope).toBe('credentialTypePolicy:manage');
		},
	);

	it.each(routeCases)(
		'$handlerName is global-only unless it addresses a project',
		({ handlerName, route }) => {
			expect(route.accessScope?.globalOnly).toBe(!projectHandlers.has(handlerName));
		},
	);

	it.each(routeCases)(
		'$handlerName is gated by the node type policies license feature',
		({ route }) => {
			expect(route.licenseFeature).toBe(LICENSE_FEATURES.TYPE_AVAILABILITY_POLICIES);
		},
	);

	it.each(routeCases)(
		'$handlerName documents a success status and the 503 for an inactive module',
		({ route }) => {
			expect(route.successStatus).toBeDefined();
			expect(route.errorResponses?.some((response) => response.status === 503)).toBe(true);
		},
	);

	it.each(routeCases)('$handlerName declares a response DTO unless it answers 204', ({ route }) => {
		if (route.successStatus === 204) {
			expect(route.responseDto).toBeUndefined();
		} else {
			expect(route.responseDto).toBeDefined();
		}
	});
});

describe('CredentialTypePoliciesPublicController with the module disabled', () => {
	const moduleRegistry = mock<ModuleRegistry>();
	const controller = new CredentialTypePoliciesPublicController(moduleRegistry);
	const req = mock<AuthenticatedRequest>();
	const res = mock<Response>();

	beforeEach(() => {
		moduleRegistry.isActive.mockReturnValue(false);
	});

	it('answers 503 before touching the service', async () => {
		await expect(controller.getCredentialTypeInstancePolicy()).rejects.toThrow(
			ServiceUnavailableError,
		);
		await expect(controller.getCredentialTypeProjectPolicy(req, res, 'project-id')).rejects.toThrow(
			ServiceUnavailableError,
		);
		await expect(controller.getCredentialTypePolicyDocument(req, res, 'policy-id')).rejects.toThrow(
			ServiceUnavailableError,
		);
		await expect(
			controller.getCredentialTypePolicyAttachments(req, res, 'scope-id'),
		).rejects.toThrow(ServiceUnavailableError);
		await expect(
			controller.deleteCredentialTypePolicyDocument(req, res, 'policy-id'),
		).rejects.toThrow(ServiceUnavailableError);

		expect(moduleRegistry.isActive).toHaveBeenCalledWith('type-availability-policies');
	});
});

describe('CredentialTypePoliciesPublicController handler bodies', () => {
	const moduleRegistry = mock<ModuleRegistry>();
	const service = mock<TypeAvailabilityPolicyService>();
	const controller = new CredentialTypePoliciesPublicController(moduleRegistry);
	const req = mock<AuthenticatedRequest>({ user: mock<User>({ id: 'user-id' }) });
	const res = mock<Response>();

	beforeEach(() => {
		moduleRegistry.isActive.mockReturnValue(true);
		Container.set(TypeAvailabilityPolicyService, service);
	});

	afterEach(() => {
		Container.reset();
	});

	const rules = [
		{ id: 'r1', action: 'deny' as const, selector: { kind: 'name' as const, value: 'a.b' } },
	];

	const effectivePolicy: EffectivePolicy = {
		scopeId: 'scope-id',
		kind: CREDENTIAL_TYPES_KIND,
		projectId: null,
		defaultAction: 'allow',
		version: 3,
		rules,
		attachments: [],
	};

	const effectiveWrite = {
		scopeId: 'scope-id',
		defaultAction: 'deny' as const,
		version: 4,
		rules,
		warnings: [{ kind: 'shadowed' as const, ruleId: 'r2', shadowedByRuleId: 'r1' }],
	};

	it('getCredentialTypePolicyAttachments reads the credential type scope with extends rules', async () => {
		const result = {
			attachments: [
				{
					policyId: 'policy-id',
					rules: [
						{
							id: 'r1',
							action: 'deny' as const,
							selector: { kind: 'extends' as const, value: 'oAuth2Api' },
						},
					],
					priority: 5,
					isFloor: true,
				},
			],
			version: 3,
		};
		service.getAttachments.mockResolvedValue(result);

		expect(await controller.getCredentialTypePolicyAttachments(req, res, 'scope-id')).toEqual(
			result,
		);
		expect(service.getAttachments).toHaveBeenCalledWith(CREDENTIAL_TYPES_KIND, 'scope-id');
	});

	it('getCredentialTypeInstancePolicy reads the null-project scope and maps the response', async () => {
		service.getEffectivePolicy.mockResolvedValue(effectivePolicy);

		const result = await controller.getCredentialTypeInstancePolicy();

		expect(service.getEffectivePolicy).toHaveBeenCalledWith(CREDENTIAL_TYPES_KIND, null);
		expect(result).toEqual({
			scopeId: effectivePolicy.scopeId,
			rules: effectivePolicy.rules,
			defaultAction: effectivePolicy.defaultAction,
			version: effectivePolicy.version,
		});
	});

	it('getCredentialTypeProjectPolicy reads the given project scope and maps the response', async () => {
		service.getEffectivePolicy.mockResolvedValue({ ...effectivePolicy, projectId: 'project-id' });

		const result = await controller.getCredentialTypeProjectPolicy(req, res, 'project-id');

		expect(service.getEffectivePolicy).toHaveBeenCalledWith(CREDENTIAL_TYPES_KIND, 'project-id');
		expect(result).toEqual({
			scopeId: effectivePolicy.scopeId,
			rules: effectivePolicy.rules,
			defaultAction: effectivePolicy.defaultAction,
			version: effectivePolicy.version,
		});
	});

	it('putCredentialTypeInstancePolicy forwards rules, defaultAction, version, and the caller id, and maps the result', async () => {
		service.setEffectivePolicy.mockResolvedValue(effectiveWrite);
		const dto = { rules, defaultAction: 'deny', version: 3 } as PutCredentialTypeInstancePolicyDto;

		const result: CredentialTypePolicyEffectiveWriteResultPublicDto =
			await controller.putCredentialTypeInstancePolicy(req, res, dto);

		expect(service.setEffectivePolicy).toHaveBeenCalledWith(
			CREDENTIAL_TYPES_KIND,
			null,
			{ rules: dto.rules, defaultAction: dto.defaultAction },
			dto.version,
			'user-id',
		);
		expect(result).toEqual({
			scopeId: effectiveWrite.scopeId,
			rules: effectiveWrite.rules,
			defaultAction: effectiveWrite.defaultAction,
			version: effectiveWrite.version,
			warnings: effectiveWrite.warnings,
		});
	});

	it('putCredentialTypeProjectPolicy forwards the project id, rules, defaultAction, version, and the caller id, and maps the result', async () => {
		service.setEffectivePolicy.mockResolvedValue(effectiveWrite);
		const dto = { rules, defaultAction: 'deny', version: 3 } as PutCredentialTypeProjectPolicyDto;

		const result = await controller.putCredentialTypeProjectPolicy(req, res, 'project-id', dto);

		expect(service.setEffectivePolicy).toHaveBeenCalledWith(
			CREDENTIAL_TYPES_KIND,
			'project-id',
			{ rules: dto.rules, defaultAction: dto.defaultAction },
			dto.version,
			'user-id',
		);
		expect(result).toEqual({
			scopeId: effectiveWrite.scopeId,
			rules: effectiveWrite.rules,
			defaultAction: effectiveWrite.defaultAction,
			version: effectiveWrite.version,
			warnings: effectiveWrite.warnings,
		});
	});
});
